+// Main
+// ---------------------------------------------------------------------------
+async function main(): Promise<void> {
+  console.log("=== Azure Event Hubs – Send & Receive Demo ===\n");
+
+  await sendEvents();
+  console.log();
+  await receiveEvents();
+}
+
+main().catch((err) => {
+  console.error("Fatal error:", err);
+  process.exit(1);
+});
